From 2807df9a4aa14da5aef6d6ab7b43110d7c113820 Mon Sep 17 00:00:00 2001
From: Nick Wellnhofer <wellnhofer@aevum.de>
Date: Tue, 6 Feb 2024 12:07:19 +0100
Subject: [PATCH] valid: Fix another use-after-free in xmlAddIDSafe

Short-lived regression.
---
 valid.c | 10 ++++++----
 1 file changed, 6 insertions(+), 4 deletions(-)

diff --git a/valid.c b/valid.c
index ed6eeb2..b1b0001 100644
--- a/valid.c
+++ b/valid.c
@@ -2324,12 +2324,14 @@ xmlAddIDSafe(xmlDocPtr doc, const xmlChar *value, xmlAttrPtr attr,
             /*
              * Update the attribute to make entities work.
              */
-            if (ret->attr != NULL) {
-                ret->attr->id = NULL;
-                ret->attr = attr;
+            if (!streaming) {
+                if (ret->attr != NULL) {
+                    ret->attr->id = NULL;
+                    ret->attr = attr;
+                }
+                attr->id = ret;
             }
 	    attr->atype = XML_ATTRIBUTE_ID;
-            attr->id = ret;
             return(0);
         }
     }
